-- The descriptor fields header: each field's dword index from the start of an object's descriptor.

local M = {}

M.path = "include/wxl/offsets/tables/update_fields.hpp"

function M.render(model)
  local out = {
    "// SPDX-License-Identifier: GPL-3.0-or-later",
    "// Generated by tools/offsets/gen.lua from atlas data/tables/update_fields.lua: do not edit.",
    "#pragma once",
    "",
    "#include <cstdint>",
    "",
    "namespace wxl::offsets::fields",
    "{",
  }
  for _, uf in ipairs(model.update_fields) do
    for _, f in ipairs(uf.value.fields or {}) do
      out[#out + 1] = string.format("    inline constexpr uint32_t %s = 0x%X; // %s, %d dword(s)", f.name, f.index, f.value or "?", f.size)
    end
  end
  out[#out + 1] = "}"
  return table.concat(out, "\n") .. "\n"
end

return M
